// Sentientia LMS Live — wordcloud loader — Phase E.5.
//
// Owns the "render a tag-cloud into a panel" capability. Mirrors the
// theme_airpayux/chart_loader.js pattern (chip-N, audit F-14): one
// module owns the renderer, callers depend on its API not the
// underlying library.
//
// Default implementation = pure DOM + CSS classes (cloud-size-1 …
// cloud-size-5). No vendor dependency. To swap for d3-cloud later,
// replace the render() body — every caller (wordcloud_updater, plus
// any future use-cases) keeps working.
//
// Public API (also exposed on window.SentientiaWordCloud):
//   render(panel, tally)    — mutate panel's .sentientia-wordcloud
//                              children to reflect tally
//   computeSize(count, max) — pick a CSS bucket class from a count
//
// XSS-safety: only textContent + className + dataset are mutated. We
// never set innerHTML — even hostile SSE payloads can only land in
// textContent.
//
// Built as named-define ES5 for the bundled context.
define('local_sentientia_live/wordcloud_loader', [], function() {
    'use strict';

    var SIZE_BUCKETS = [
        'cloud-size-1',
        'cloud-size-2',
        'cloud-size-3',
        'cloud-size-4',
        'cloud-size-5'
    ];

    function computeSize(count, max) {
        if (typeof count !== 'number' || count <= 0) {
            return SIZE_BUCKETS[0];
        }
        if (typeof max !== 'number' || max <= 0) {
            return SIZE_BUCKETS[0];
        }
        var ratio = count / max;
        var bucket = Math.ceil(ratio * SIZE_BUCKETS.length);
        if (bucket < 1) { bucket = 1; }
        if (bucket > SIZE_BUCKETS.length) { bucket = SIZE_BUCKETS.length; }
        return SIZE_BUCKETS[bucket - 1];
    }

    function render(panel, tally) {
        if (!panel || !tally || typeof tally !== 'object') { return; }
        var container = panel.querySelector('.sentientia-wordcloud');
        if (!container) { return; }

        // Take top 50 to keep the cloud readable on small screens.
        var entries = [];
        Object.keys(tally).forEach(function(w) {
            var c = Number(tally[w]);
            if (isNaN(c)) { c = 0; }
            entries.push({word: String(w), count: c});
        });
        entries.sort(function(a, b) { return b.count - a.count; });
        entries = entries.slice(0, 50);

        if (entries.length === 0) { return; }
        var max = entries[0].count > 0 ? entries[0].count : 1;

        var existing = {};
        var nodes = container.querySelectorAll('.sentientia-wordcloud-word');
        for (var i = 0; i < nodes.length; i++) {
            var node = nodes[i];
            var w = node.dataset.word || (node.textContent || '').trim();
            if (w) {
                existing[w] = node;
            }
        }

        var seen = {};
        entries.forEach(function(entry) {
            var sizeClass = computeSize(entry.count, max);
            seen[entry.word] = true;
            var node = existing[entry.word];
            if (!node) {
                node = document.createElement('span');
                node.className = 'sentientia-wordcloud-word ' + sizeClass;
                node.textContent = entry.word;
                node.dataset.word = entry.word;
                container.appendChild(node);
            } else {
                SIZE_BUCKETS.forEach(function(b) {
                    node.classList.remove(b);
                });
                node.classList.add(sizeClass);
            }
            node.dataset.count = String(entry.count);
            node.setAttribute('title', String(entry.count));
        });

        // Remove nodes for words that fell out of the top-50 window.
        Object.keys(existing).forEach(function(word) {
            if (!seen[word]) {
                existing[word].parentNode.removeChild(existing[word]);
            }
        });
    }

    function init() {
        if (typeof window !== 'undefined') {
            window.SentientiaWordCloud = {
                render: render,
                computeSize: computeSize
            };
        }
    }

    return {
        init: init,
        render: render,
        computeSize: computeSize
    };
});
